+    border: 1px solid #dee2e6;
+    background: #fff;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-move:hover {
+    background: #e9ecef;
+}
+
+.btn-add-task {
+    width: 100%;
+    padding: 0.5rem;
+    border: 1px dashed #adb5bd;
+    background: transparent;
+    border-radius: 4px;
+    cursor: pointer;
+    color: #6c757d;
+    font-weight: 500;
+}
+
+.btn-add-task:hover {
+    background: #e9ecef;
+}
+
+.add-task-form {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+    background: #fff;
+    padding: 0.75rem;
+    border-radius: 6px;
+    border: 1px solid #dee2e6;
+}
+
+.add-task-form input,
+.add-task-form select {
+    padding: 0.4rem 0.6rem;
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+    font-size: 0.9rem;
+}
+
+.form-actions {
+    display: flex;
+    gap: 0.5rem;
+}
+
+.btn-save {
+    padding: 0.4rem 0.8rem;
+    background: #0d6efd;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-save:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-cancel {
+    padding: 0.4rem 0.8rem;
+    background: #6c757d;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.loading-message {
+    text-align: center;
+    padding: 2rem;
+    color: #6c757d;
+}
+
+.error-message {
+    text-align: center;
+    padding: 2rem;
+    color: #dc3545;
+}
+
+.error-message button {
+    margin-top: 1rem;
+    padding: 0.5rem 1rem;
+    background: #dc3545;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+

